import{z as s,x as i,o as E,c as p,q as r,j as l,D as e,d as o,s as n,S as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"递归定理","description":"","frontmatter":{"title":"递归定理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/recursion-theorem.md","filePath":"cs/recursion-theorem.md","lastUpdated":1791063341000}'),B={name:"cs/recursion-theorem.md"};function d(_,a,c,m,h,g){const t=i("Mermaid");return E(),p("div",null,[a[2]||(a[2]=r('<h1 id="递归定理" tabindex="-1">递归定理 <a class="header-anchor" href="#递归定理" aria-label="Permalink to &quot;递归定理&quot;">​</a></h1><div class="epigraph"><p>任何可计算变换 $t$，都有机器 $M$ 使 $M$ 与 $t(\\langle M\\rangle)$ 计算同一函数；程序可以获得自身的文本。</p><footer>—— 据 Kleene；Sipser 整理</footer></div><p>上一课<a href="/cs/rice-theorem">Rice</a>谈外延性质，机器看不到自己的编码——除非我们另给。缺口是<strong>Kleene 递归定理</strong>（不动点）：存在自指程序。病毒「把自身复制进输出」、构造「打印自己的源」都落在这里；后课 Kolmogorov 也要用最短描述的自指。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可计算函数 \\(t\\) 把编码变成编码。递归定理：存在 \\(e\\)，\\(\\{e\\}=\\{t(e)\\}\\)（同一部分函数）。构造：先做「给定 \\(w\\)，算出 \\(\\langle P_w\\rangle\\) 再跑 \\(t(\\langle P_w\\rangle)\\) 于输入」，其中 \\(P_w\\) 是「先写出 \\(w\\) 再做……」的机器。对角地喂入自身描述。本课要存在性与用法，不把组合子 \\(Y\\) 提前（那是 λ 课）。</p><p>没有定理时，TM 的 \\(\\delta\\) 表里写不进「本机的 \\(\\langle M\\rangle\\)」——表是有限的，编码依赖于整张表。递归定理说：先允许一个变换假定「编码会填进来」，再保证有填法一致。应用：构造 \\(M\\) 在输入 \\(w\\) 上检查 \\(w=\\langle M\\rangle\\) 之类的机器，证明仍合法。</p><h3 id="不是数学归纳法" tabindex="-1">不是数学归纳法 <a class="header-anchor" href="#不是数学归纳法" aria-label="Permalink to &quot;不是数学归纳法&quot;">​</a></h3><p>名字里的 recursion 是自指，不是「对 \\(n\\) 归纳」。程序递归调用自身是其推论：调用时编码已知。</p><p><span class="marginnote">Kleene 第二递归定理。Sipser 用「获得自身描述」的应用版。Quine（打印自身的程序）是同一现象的玩具。固定点在 λ 课用 \\(Y\\)，对象换成项。</span></p><p><span class="marginnote">直觉类比：把它想象成「一台复印机印出的说明书上，恰好印着这台复印机的完整设计图」。图灵机的转移表本来写不下「整张表自己」，递归定理证明存在一种自洽的填法——把自我描述「折」进了有限表里。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>应用：存在 \\(M\\) 输出 \\(\\langle M\\rangle\\) 然后停（Quine）。不要用定理声称「一切自修改代码都不可分析」——Rice 已经管语义；这里管的是描述的存在。</p>',12)),(E(),l(A,null,{default:e(()=>[n(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%8F%AF%E8%AE%A1%E7%AE%97%20t%22%5D%20--%3E%20FP%5B%22%E5%AD%98%E5%9C%A8%20M%20%E2%89%A1%20t%E2%9F%A8M%E2%9F%A9%22%5D%0A%20%20FP%20--%3E%20SELF%5B%22%E7%A8%8B%E5%BA%8F%E5%BE%97%E5%88%B0%E8%87%AA%E8%BA%AB%E6%96%87%E6%9C%AC%22%5D%0A%20%20SELF%20--%3E%20LATER%5B%22Kolmogorov%20%2F%20%E7%97%85%E6%AF%92%E5%A4%8D%E5%88%B6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了自指，才能写「最短程序」时出现的循环论证：描述「比这个还短的程序不存在」会指涉自身长度。下一课 Kolmogorov 复杂度不可计算，递归定理提供合法性。也可用来给 Rice 另一种证明，本课不换证明。</p><p>与停机的关系：自指程序仍是普通 TM，停机问题并不因此可解。</p><p><span class="marginnote">术语翻译：递归定理说的「递归」是<strong>自指</strong>——允许机器在构造阶段引用「本机编码」这个占位符，再由数学保证存在一种填法使整体自洽；程序运行时递归调用自己只是推论，不是定理本体。</span></p><p><span class="marginnote">常见误区：初学者容易以为递归定理要求操作系统提供「读自己源文件」的功能。实际上它只保证<strong>存在</strong>一台机器，其行为与「对自己的编码做变换 \\(t\\) 再运行」相同；能不能真的在运行时读到源码是工程问题，定理管的是数学上合法。</span></p>',5)),(E(),l(A,null,{default:e(()=>[n(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E7%BB%99%E5%AE%9A%E5%8F%AF%E8%AE%A1%E7%AE%97%E5%8F%98%E6%8D%A2%20t%22%5D%20--%3E%20P%5B%22%E6%9E%84%E9%80%A0%E5%8F%82%E6%95%B0%E5%8C%96%E6%9C%BA%E5%99%A8%20P_w%EF%BC%9A%E5%85%88%E8%BE%93%E5%87%BA%20w%20%E5%86%8D%E6%8C%89%20w%20%E8%A1%8C%E4%BA%8B%22%5D%0A%20%20P%20--%3E%20ENC%5B%22%E5%AF%B9%E6%AF%8F%E4%B8%AA%20w%20%E7%AE%97%E5%87%BA%E7%BC%96%E7%A0%81%20%E2%9F%A8P_w%E2%9F%A9%22%5D%0A%20%20ENC%20--%3E%20DIAG%5B%22%E5%AF%B9%E8%A7%92%EF%BC%9A%E6%8A%8A%20w%20%E8%87%AA%E8%BA%AB%E5%A1%AB%E8%BF%9B%20t%EF%BC%8C%E5%BE%97%20t(%E2%9F%A8P_w%E2%9F%A9)%22%5D%0A%20%20DIAG%20--%3E%20FIX%5B%22%E6%89%BE%E4%B8%8D%E5%8A%A8%E7%82%B9%20w*%EF%BC%9AP_w*%20%E4%B8%8E%20t(%E2%9F%A8P_w*%E2%9F%A9)%20%E5%90%8C%E5%87%BD%E6%95%B0%22%5D%0A%20%20FIX%20--%3E%20M%5B%22%E8%BE%93%E5%87%BA%E6%9C%BA%E5%99%A8%20M%EF%BC%9A%E5%90%88%E6%B3%95%E8%87%AA%E5%B8%A6%E6%BA%90%E7%A0%81%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p>构造病毒「把自身写入文件」在模型里合法，不增加计算类。证明停机时不能假设「程序不知道自己的源」——它可以知道。Kolmogorov 课用自指封住「最短不可压缩串」的描述。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 \\(s\\)-\\(m\\)-\\(n\\) 定理的全部细节，不写组合逻辑。不讨论生物学或实际恶意软件。后课默认：需要「机器带着自己的源」时，递归定理保证存在。下一课把最短描述当成复杂度。</p><p>自指给出的 \\(M\\) 仍是普通图灵机，不扩大 RE。后课最短描述的悖论式构造因此合法：描述可以谈论「本串的 \\(K\\)」。λ 侧的对应物是 \\(Y\\)，不是本课对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>任意可计算 \\(t\\) 有不动点机器：\\(M\\) 与 \\(t(\\langle M\\rangle)\\) 同函数。</li><li>程序可以合法地引用自身编码。</li><li>自指不增加可计算类，只增加构造手法。</li><li>后课 \\(K(x)\\) 的自指描述靠本课才合法。</li><li>出处：Kleene；Sipser。</li></ul>',6))])}const T=s(B,[["render",d]]);export{F as __pageData,T as default};
